export const parentRoleLabel=role=>({mother:'Mama',father:'Tata',unspecified:'Nie określono'}[role]||'Nie określono');
export function onboardingHtml(brand,icon,state,importantIcon){
  const choices=(key,items)=>items.map(([value,label,art])=>`<button type="button" data-choice="${key}" data-value="${value}" class="onboarding-choice ${state[key]===value?'selected':''}" aria-pressed="${state[key]===value}">${art||''}<span>${label}</span><i aria-hidden="true"></i></button>`).join('');
  return `<main class="welcome onboarding-page">${brand}<div class="onboarding-layout"><section class="onboarding-intro"><span class="eyebrow">Wspieramy od początku</span><h1>Wielka przygoda.<br>Małe kroki.</h1><p>Jesteśmy obok, tydzień po tygodniu.</p><img class="onboarding-hero" src="assets/onboarding-pregnancy.png" alt=""><p>Wasz rytm. Wasza droga.</p></section><form id="onboarding-form" novalidate><fieldset id="onboarding-role"><legend>Kim jesteś?</legend><div class="onboarding-options role-options">${choices('role',[['mother','Mamą'],['father','Tatą'],['unspecified','Nie chcę podawać']])}</div><p class="choice-error" role="alert" hidden>${importantIcon}Wybierz rolę lub zaznacz „Nie chcę podawać”.</p></fieldset><fieldset id="onboarding-stage"><legend>Na jakim etapie jesteście teraz?</legend><div class="onboarding-options stage-options">${choices('stage',[['pregnancy','Oczekujemy dziecka','<img src="assets/onboarding-pregnancy.png" alt="">'],['child','Dziecko jest już z nami','<img src="assets/onboarding-baby.png" alt="">'],['planning','Dopiero planujemy dziecko']])}</div><p class="choice-error" role="alert" hidden>${importantIcon}Wybierz ciążę, narodzone dziecko lub planowanie.</p></fieldset><fieldset id="onboarding-gender" ${state.stage==='planning'?'hidden':''}><legend>Płeć dziecka</legend><div class="onboarding-options role-options">${choices('gender',[['boy','Chłopiec'],['girl','Dziewczynka'],['unspecified','Brak informacji']])}</div><p class="field-help">Ten wybór możecie później zmienić w profilu.</p><p class="choice-error" role="alert" hidden>${importantIcon}Wybierz płeć lub zaznacz „Brak informacji”.</p></fieldset><button class="primary" type="submit">Zaczynamy ${icon}</button></form></div></main>`;
}
